177→```typescript
178→import type { SdkContext } from '@cipherbox/sdk-core';
179→import { createAxiosInstance, type ApiClientConfig } from '@cipherbox/api-client';
180→
181→/**
182→ * Create an SdkContext for headless sdk-core calls from a PoolClient.
183→ *
184→ * Constructs a fresh axiosInstance with 401 interceptor so that
185→ * headless workloads get automatic token refresh.
186→ */
187→export function createSdkContext(pc: PoolClient): SdkContext {
188→  // Mutable token holder -- updated by 401 interceptor
189→  let currentToken = pc.accessToken;
190→
191→  // Shared refresh promise to coalesce concurrent 401 re-auths
192→  let refreshPromise: Promise<string> | null = null;
193→
194→  const config: ApiClientConfig = {
195→    baseUrl: API_URL,
196→    getAccessToken: async () => currentToken,
197→    refreshAccessToken: async () => {
198→      if (!refreshPromise) {
199→        refreshPromise = reAuthenticate(pc.email).finally(() => {
200→          refreshPromise = null;
201→        });
202→      }
203→      const newToken = await refreshPromise;
204→      currentToken = newToken;
205→      pc.accessToken = newToken;
206→      return newToken;
207→    },
208→    defaultHeaders: THROTTLE_BYPASS ? { 'X-Throttle-Bypass': THROTTLE_BYPASS } : undefined,
209→  };
210→
211→  const axiosInstance = createAxiosInstance(config);
212→
213→  return {
214→    apiUrl: API_URL,
215→    getAccessToken: async () => currentToken,
216→    axiosInstance,
217→  };
218→}
219→```
