298→```typescript
299→/**
300→ * SDK-Core Headless Workloads
301→ *
302→ * Direct sdk-core function calls without CipherBoxClient overhead.
303→ * Used for bottleneck isolation in load test scenarios.
304→ */
305→
306→import type { SdkContext } from '@cipherbox/sdk-core';
307→import * as sdkCore from '@cipherbox/sdk-core';
308→import type { PoolClient } from '../harness/client-pool';
309→import { createSdkContext } from '../harness/client-pool';
310→
311→const API_URL = process.env.LOAD_TEST_API_URL ?? 'http://localhost:3000';
312→
313→export interface SdkWorkloadClient {
314→  pc: PoolClient;
315→  ctx: SdkContext;
316→}
317→
318→/** Prepare a PoolClient for headless sdk-core workloads. */
319→export function prepareSdkClient(pc: PoolClient): SdkWorkloadClient {
320→  return { pc, ctx: createSdkContext(pc) };
321→}
322→
323→/** IPNS publish + resolve cycle workload. */
324→export async function runIpnsPublishWorkload(
325→  swc: SdkWorkloadClient,
326→  opts: { cycles: number }
327→): Promise<void> {
328→  const { pc, ctx } = swc;
329→  for (let i = 0; i < opts.cycles; i++) {
330→    // Publish
331→    try {
332→      await pc.metrics.measure('sdkIpnsPublish', () =>
333→        sdkCore.createAndPublishIpnsRecord({
334→          ipnsPrivateKey: pc.rootIpnsKeypair.privateKey,
335→          ipnsName: pc.rootIpnsName,
336→          metadataCid: `bafybeig${Date.now().toString(36)}${i.toString(36)}`,
337→          sequenceNumber: BigInt(i + 100),
338→          ctx,
339→        })
340→      );
341→    } catch (err) {
342→      pc.metrics.recordError('sdkIpnsPublish', err as Error);
343→    }
344→
345→    // Resolve
346→    try {
347→      await pc.metrics.measure('sdkIpnsResolve', () =>
348→        sdkCore.resolveIpnsRecord(pc.rootIpnsName, ctx)
349→      );
350→    } catch (err) {
351→      pc.metrics.recordError('sdkIpnsResolve', err as Error);
352→    }
353→  }
354→}
355→
356→/** Upload pipeline workload (encrypt + pin + IPNS publish). */
357→export async function runUploadPipelineWorkload(
358→  swc: SdkWorkloadClient,
359→  opts: { fileCount: number; fileSizeBytes: number }
360→): Promise<void> {
361→  const { pc, ctx } = swc;
362→  for (let i = 0; i < opts.fileCount; i++) {
363→    const data = new Uint8Array(opts.fileSizeBytes);
364→    crypto.getRandomValues(data);
365→    const fileName = `sdk-load-${pc.id}-${i}.bin`;
366→
367→    try {
368→      await pc.metrics.measure(
369→        'sdkUploadFile',
370→        () =>
371→          sdkCore.uploadFile({
372→            ctx,
373→            folderKey: pc.rootFolderKey,
374→            ipnsPrivateKey: pc.rootIpnsKeypair.privateKey,
375→            ipnsName: pc.rootIpnsName,
376→            data,
377→            fileName,
378→            mimeType: 'application/octet-stream',
379→          }),
380→        opts.fileSizeBytes
381→      );
382→    } catch (err) {
383→      pc.metrics.recordError('sdkUploadFile', err as Error);
384→    }
385→  }
386→}
387→
388→/** Folder metadata read workload (IPNS resolve + IPFS fetch + decrypt). */
389→export async function runFolderReadWorkload(
390→  swc: SdkWorkloadClient,
391→  opts: { cycles: number }
392→): Promise<void> {
393→  const { pc, ctx } = swc;
394→  for (let i = 0; i < opts.cycles; i++) {
395→    try {
396→      await pc.metrics.measure('sdkFolderRead', () =>
397→        sdkCore.fetchAndDecryptMetadata({
398→          ipnsName: pc.rootIpnsName,
399→          folderKey: pc.rootFolderKey,
400→          ctx,
401→        })
402→      );
403→    } catch (err) {
404→      pc.metrics.recordError('sdkFolderRead', err as Error);
405→    }
406→  }
407→}
408→```
