  1→/**
  2→ * @cipherbox/core - Device Registry Schema Validation
  3→ *
  4→ * Runtime validation for DeviceRegistry JSON after decryption.
  5→ * Uses manual checks consistent with existing codebase patterns
  6→ * (see folder/metadata.ts validateFolderMetadata).
  7→ *
  8→ * Supports v1 -> v2 migration:
  9→ * - v1 registries with empty ipHash are accepted and migrated to v2 with zero placeholder
 10→ * - v2 registries are validated strictly (ipHash must be valid 64-char hex)
 11→ */
 12→
 13→import { CryptoError } from '@cipherbox/crypto';
 14→import type { DeviceRegistry, DeviceAuthStatus, DevicePlatform, DeviceEntry } from './types';
 15→
 16→const VALID_STATUSES: DeviceAuthStatus[] = ['pending', 'authorized', 'revoked'];
 17→const VALID_PLATFORMS: DevicePlatform[] = ['web', 'macos', 'linux', 'windows'];
 18→const HEX_REGEX = /^[0-9a-fA-F]+$/;
 19→
 20→/**
 21→ * Validate a parsed JSON object as a DeviceRegistry.
 22→ *
 23→ * Handles both v1 and v2 formats:
 24→ * - v1: Migrated to v2 (lenient ipHash validation, fills zero placeholder)
 25→ * - v2: Strict validation (ipHash must be valid 64-char hex)
 26→ *
 27→ * Throws CryptoError with code 'DECRYPTION_FAILED' on validation failure
 28→ * to avoid leaking schema details to attackers.
 29→ *
 30→ * @param data - Unknown parsed JSON data
 31→ * @returns Validated DeviceRegistry (always v2)
 32→ * @throws CryptoError if validation fails
 33→ */
 34→export function validateDeviceRegistry(data: unknown): DeviceRegistry {
 35→  if (typeof data !== 'object' || data === null) {
 36→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 37→  }
 38→
 39→  const obj = data as Record<string, unknown>;
 40→  const version = obj.version;
 41→
 42→  if (version === 'v1') {
 43→    return migrateV1ToV2(obj);
 44→  }
 45→  if (version === 'v2') {
 46→    return validateV2Registry(obj);
 47→  }
 48→  throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 49→}
 50→
 51→/**
 52→ * Migrate a v1 registry to v2 format.
 53→ *
 54→ * Lenient on ipHash: accepts empty strings from v1 (known bug in useAuth.ts)
 55→ * and fills them with a 64-char zero placeholder.
 56→ */
 57→function migrateV1ToV2(obj: Record<string, unknown>): DeviceRegistry {
 58→  if (
 59→    typeof obj.sequenceNumber !== 'number' ||
 60→    !Number.isInteger(obj.sequenceNumber) ||
 61→    obj.sequenceNumber < 0
 62→  ) {
 63→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 64→  }
 65→  if (!Array.isArray(obj.devices)) {
 66→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 67→  }
 68→
 69→  const devices = (obj.devices as Record<string, unknown>[]).map((d) => {
 70→    validateDeviceEntryBase(d);
 71→    const ipHash = d.ipHash as string;
 72→    return {
 73→      ...(d as unknown as DeviceEntry),
 74→      // Accept empty ipHash from v1 (known bug) -- fill with zero placeholder
 75→      ipHash: ipHash.length === 64 && HEX_REGEX.test(ipHash) ? ipHash : '0'.repeat(64),
 76→    };
 77→  }) as DeviceEntry[];
 78→
 79→  return {
 80→    version: 'v2',
 81→    sequenceNumber: obj.sequenceNumber as number,
 82→    devices,
 83→  };
 84→}
 85→
 86→/**
 87→ * Validate a v2 registry with strict validation.
 88→ */
 89→function validateV2Registry(obj: Record<string, unknown>): DeviceRegistry {
 90→  if (
 91→    typeof obj.sequenceNumber !== 'number' ||
 92→    !Number.isInteger(obj.sequenceNumber) ||
 93→    obj.sequenceNumber < 0
 94→  ) {
 95→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 96→  }
 97→  if (!Array.isArray(obj.devices)) {
 98→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 99→  }
100→
101→  for (const device of obj.devices) {
102→    validateDeviceEntry(device); // Strict v2 validation (ipHash must be valid 64 hex)
103→  }
104→
105→  return obj as unknown as DeviceRegistry;
106→}
107→
108→/**
109→ * Validate device entry base fields (everything EXCEPT ipHash length/hex).
110→ * Used by v1 migration where ipHash may be empty.
111→ */
112→function validateDeviceEntryBase(data: unknown): void {
113→  if (typeof data !== 'object' || data === null) {
114→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
115→  }
116→
117→  const entry = data as Record<string, unknown>;
118→
119→  // Required string fields
120→  const requiredStrings = [
121→    'deviceId',
122→    'publicKey',
123→    'name',
124→    'platform',
125→    'appVersion',
126→    'deviceModel',
127→    'ipHash',
128→    'status',
129→  ];
130→  for (const field of requiredStrings) {
131→    if (typeof entry[field] !== 'string') {
132→      throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
133→    }
134→  }
135→
136→  // Hex format + length validation for cryptographic fields (except ipHash -- handled by caller)
137→  const deviceId = entry.deviceId as string;
138→  if (deviceId.length !== 64 || !HEX_REGEX.test(deviceId)) {
139→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
140→  }
141→
142→  const publicKey = entry.publicKey as string;
143→  if (publicKey.length !== 64 || !HEX_REGEX.test(publicKey)) {
144→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
145→  }
146→
147→  // Max length for free-text fields
148→  if ((entry.name as string).length > 200) {
149→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
150→  }
151→  if ((entry.appVersion as string).length > 50) {
152→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
153→  }
154→  if ((entry.deviceModel as string).length > 200) {
155→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
156→  }
157→
158→  // Validate status is a known value
159→  if (!VALID_STATUSES.includes(entry.status as DeviceAuthStatus)) {
160→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
161→  }
162→
163→  // Validate platform is a known value
164→  if (!VALID_PLATFORMS.includes(entry.platform as DevicePlatform)) {
165→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
166→  }
167→
168→  // Validate timestamp fields
169→  if (typeof entry.createdAt !== 'number' || typeof entry.lastSeenAt !== 'number') {
170→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
171→  }
172→
173→  // Validate nullable fields
174→  if (entry.revokedAt !== null && typeof entry.revokedAt !== 'number') {
175→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
176→  }
177→  if (entry.revokedBy !== null && typeof entry.revokedBy !== 'string') {
178→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
179→  }
180→}
181→
182→/**
183→ * Validate an individual device entry with strict ipHash validation.
184→ * Used for v2 registries where ipHash must be a valid 64-char hex string.
185→ */
186→function validateDeviceEntry(data: unknown): void {
187→  validateDeviceEntryBase(data);
188→  const entry = data as Record<string, unknown>;
189→  const ipHash = entry.ipHash as string;
190→  if (ipHash.length !== 64 || !HEX_REGEX.test(ipHash)) {
191→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
192→  }
193→}
