  1→/**
  2→ * @cipherbox/sdk - Bin operations
  3→ *
  4→ * Extracted from: apps/web/src/services/bin.service.ts (962 LOC)
  5→ * All Zustand store access replaced with explicit parameters.
  6→ *
  7→ * Bin operations manage the recycle bin lifecycle:
  8→ * - addToBin: soft-delete (remove from folder, add to bin)
  9→ * - restoreFromBin: undo soft-delete (remove from bin, add back to folder)
 10→ * - permanentDeleteFromBin: hard-delete with CID cleanup
 11→ * - emptyBin: permanently delete all bin entries
 12→ * - loadBin: load current bin metadata from IPNS
 13→ *
 14→ * Each function takes explicit params instead of reading from stores.
 15→ */
 16→
 17→import type { SdkContext, TeeKeys } from '@cipherbox/sdk-core';
 18→import * as sdkCore from '@cipherbox/sdk-core';
 19→import {
 20→  encryptBinMetadata,
 21→  decryptBinMetadata,
 22→  deriveBinIpnsKeypair,
 23→  type BinEntry,
 24→  type RecycleBinMetadata,
 25→  type FolderChild,
 26→  type FilePointer,
 27→  type FolderEntry,
 28→} from '@cipherbox/core';
 29→import { bytesToHex, hexToBytes, wrapKey } from '@cipherbox/crypto';
 30→import type { FolderTree } from '../state/folder-tree';
 31→
 32→/** Current bin metadata version. */
 33→const BIN_METADATA_VERSION = 'v1' as const;
 34→
 35→/**
 36→ * Context for bin operations. Replaces Zustand store access.
 37→ */
 38→export type BinOperationContext = {
 39→  ctx: SdkContext;
 40→  userPrivateKey: Uint8Array;
 41→  userPublicKey: Uint8Array;
 42→  rootFolderKey: Uint8Array;
 43→  teeKeys?: TeeKeys;
 44→};
 45→
 46→/**
 47→ * Internal state for the bin (replaces useBinStore).
 48→ */
 49→export type BinState = {
 50→  entries: BinEntry[];
 51→  sequenceNumber: number;
 52→  ipnsName: string;
 53→};
 54→
 55→// ---------------------------------------------------------------------------
 56→// Internal helpers: load / save bin metadata
 57→// ---------------------------------------------------------------------------
 58→
 59→/**
 60→ * Load and decrypt bin metadata from IPNS.
 61→ */
 62→async function loadBinMetadataInternal(params: {
 63→  userPrivateKey: Uint8Array;
 64→  ctx: SdkContext;
 65→}): Promise<{
 66→  metadata: RecycleBinMetadata;
 67→  ipnsName: string;
 68→  sequenceNumber: bigint;
 69→} | null> {
 70→  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
 71→  const resolved = await sdkCore.resolveIpnsRecord(binIpns.ipnsName, params.ctx);
 72→
 73→  if (!resolved) return null;
 74→
 75→  const encryptedBytes = await sdkCore.fetchFromIpfs(params.ctx, resolved.cid);
 76→  const metadata = await decryptBinMetadata(encryptedBytes, params.userPrivateKey);
 77→
 78→  return {
 79→    metadata,
 80→    ipnsName: binIpns.ipnsName,
 81→    sequenceNumber: resolved.sequenceNumber,
 82→  };
 83→}
 84→
 85→/**
 86→ * Encrypt and publish bin metadata to IPNS.
 87→ */
 88→async function saveBinMetadata(params: {
 89→  metadata: RecycleBinMetadata;
 90→  binCtx: BinOperationContext;
 91→}): Promise<void> {
 92→  const binIpns = await deriveBinIpnsKeypair(params.binCtx.userPrivateKey);
 93→
 94→  // Encrypt metadata with user's public key (ECIES)
 95→  const encryptedBytes = await encryptBinMetadata(params.metadata, params.binCtx.userPublicKey);
 96→
 97→  // Pin to IPFS
 98→  const { cid } = await sdkCore.addToIpfs(params.binCtx.ctx, encryptedBytes);
 99→
100→  // TEE enrollment (optional)
101→  let encryptedIpnsKey: string | undefined;
102→  let keyEpoch: number | undefined;
103→
104→  if (params.binCtx.teeKeys?.currentPublicKey) {
105→    try {
106→      const teePublicKey = hexToBytes(params.binCtx.teeKeys.currentPublicKey);
107→      const wrappedKey = await wrapKey(binIpns.privateKey, teePublicKey);
108→      encryptedIpnsKey = bytesToHex(wrappedKey);
109→      keyEpoch = params.binCtx.teeKeys.currentEpoch;
110→    } catch {
111→      // TEE enrollment failure is non-blocking
112→    }
113→  }
114→
115→  // Publish IPNS record with verification
116→  await publishWithVerify({
117→    ipnsName: binIpns.ipnsName,
118→    ipnsPrivateKey: binIpns.privateKey,
119→    cid,
120→    sequenceNumber: BigInt(params.metadata.sequenceNumber),
121→    encryptedIpnsPrivateKey: encryptedIpnsKey,
122→    keyEpoch,
123→    ctx: params.binCtx.ctx,
124→  });
125→}
126→
127→/**
128→ * Publish an IPNS record and verify it is resolvable.
129→ *
130→ * Wraps createAndPublishIpnsRecord with a resolve-back verification loop.
131→ * On verify failure, retries with exponential backoff (500ms, 1000ms, 2000ms).
132→ * After all retries exhausted, does NOT throw -- the publish went through,
133→ * verification just couldn't confirm propagation.
134→ */
135→async function publishWithVerify(params: {
136→  ipnsName: string;
137→  ipnsPrivateKey: Uint8Array;
138→  cid: string;
139→  sequenceNumber: bigint;
140→  encryptedIpnsPrivateKey?: string;
141→  keyEpoch?: number;
142→  ctx: SdkContext;
143→  maxRetries?: number;
144→}): Promise<void> {
145→  const maxRetries = params.maxRetries ?? 3;
146→  for (let attempt = 0; attempt < maxRetries; attempt++) {
147→    await sdkCore.createAndPublishIpnsRecord({
148→      ipnsPrivateKey: params.ipnsPrivateKey,
149→      ipnsName: params.ipnsName,
150→      metadataCid: params.cid,
151→      sequenceNumber: params.sequenceNumber,
152→      encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
153→      keyEpoch: params.keyEpoch,
154→      ctx: params.ctx,
155→    });
156→    // Verify: resolve back to confirm DB cache was written
157→    const resolved = await sdkCore.resolveIpnsRecord(params.ipnsName, params.ctx);
158→    if (resolved) return; // Success -- record is resolvable
159→    // Exponential backoff: 500ms, 1000ms, 2000ms
160→    if (attempt < maxRetries - 1) {
161→      await new Promise((r) => setTimeout(r, 500 * Math.pow(2, attempt)));
162→    }
163→  }
164→  // After all retries, don't throw -- the publish went through, just verification failed
165→  // The record may still propagate eventually
166→}
167→
168→// ---------------------------------------------------------------------------
169→// Public API
170→// ---------------------------------------------------------------------------
171→
172→/**
173→ * Load the recycle bin metadata from IPNS.
174→ *
175→ * If no bin IPNS record exists yet (first login / never deleted anything),
176→ * returns an empty BinState so that deleteToBin can create the first record.
177→ * The old bin service handled this by creating in-memory-only empty state;
178→ * the SDK must do the same to avoid "Bin not loaded" errors on first delete.
179→ *
180→ * @returns Current bin state (never null — empty state if no record exists)
181→ */
182→export async function loadBin(params: { binCtx: BinOperationContext }): Promise<BinState> {
183→  const loaded = await loadBinMetadataInternal({
184→    userPrivateKey: params.binCtx.userPrivateKey,
185→    ctx: params.binCtx.ctx,
186→  });
187→
188→  if (!loaded) {
189→    // No bin IPNS record -- auto-repair by publishing empty bin
190→    const binIpns = await deriveBinIpnsKeypair(params.binCtx.userPrivateKey);
191→    const emptyMetadata: RecycleBinMetadata = {
192→      version: BIN_METADATA_VERSION,
193→      sequenceNumber: 1,
194→      entries: [],
195→    };
196→    // Publish empty bin to establish the IPNS record (with retry/verify)
197→    await saveBinMetadata({ metadata: emptyMetadata, binCtx: params.binCtx });
198→    return {
199→      entries: [],
200→      sequenceNumber: 1,
201→      ipnsName: binIpns.ipnsName,
202→    };
203→  }
204→
205→  return {
206→    entries: loaded.metadata.entries,
207→    sequenceNumber: loaded.metadata.sequenceNumber,
208→    ipnsName: loaded.ipnsName,
209→  };
210→}
211→
212→/**
213→ * Add item to recycle bin.
214→ *
215→ * Removes the item from the folder metadata (via deleteFromFolder),
216→ * creates a BinEntry, appends to bin metadata, and publishes both.
217→ *
218→ * @returns The removed item from the folder
219→ */
220→export async function addToBin(params: {
221→  folderIpnsName: string;
222→  childId: string;
223→  parentPath: string;
224→  folderTree: FolderTree;
225→  binState: BinState;
226→  binCtx: BinOperationContext;
227→}): Promise<{ removedItem: FolderChild; updatedBinState: BinState }> {
228→  const folder = params.folderTree.get(params.folderIpnsName);
229→  if (!folder) throw new Error('Folder not loaded');
230→
231→  // 1. Remove item from folder metadata
232→  const { updatedChildren, removedItem } = sdkCore.deleteFromFolder({
233→    children: folder.children,
234→    childId: params.childId,
235→  });
236→
237→  // 2. Publish updated folder metadata
238→  const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
239→    children: updatedChildren,
240→    folderKey: folder.folderKey,
241→    ipnsPrivateKey: folder.ipnsKeypair.privateKey,
242→    ipnsName: params.folderIpnsName,
243→    sequenceNumber: folder.sequenceNumber,
244→    ctx: params.binCtx.ctx,
245→  });
246→
247→  // 3. Update folder state
248→  folder.children = updatedChildren;
249→  folder.sequenceNumber = newSequenceNumber;
250→  folder.lastLoadedAt = Date.now();
251→  params.folderTree.set(params.folderIpnsName, folder);
252→
253→  // 4. Build bin entry
254→  const isFile = removedItem.type === 'file';
255→  const entry: BinEntry = {
256→    id: crypto.randomUUID(),
257→    itemType: isFile ? 'file' : 'folder',
258→    name: removedItem.name,
259→    originalParentIpnsName: params.folderIpnsName,
260→    originalPath: params.parentPath,
261→    deletedAt: Date.now(),
262→    size: 0,
263→    mimeType: '',
264→    filePointer: isFile ? (removedItem as FilePointer) : undefined,
265→    folderEntry: !isFile ? (removedItem as FolderEntry) : undefined,
266→  };
267→
268→  // 5. Update bin metadata and publish
269→  const updatedEntries = [...params.binState.entries, entry];
270→  const newBinSeq = params.binState.sequenceNumber + 1;
271→
272→  const metadata: RecycleBinMetadata = {
273→    version: BIN_METADATA_VERSION,
274→    sequenceNumber: newBinSeq,
275→    entries: updatedEntries,
276→  };
277→
278→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
279→
280→  const updatedBinState: BinState = {
281→    entries: updatedEntries,
282→    sequenceNumber: newBinSeq,
283→    ipnsName: params.binState.ipnsName,
284→  };
285→
286→  return { removedItem, updatedBinState };
287→}
288→
289→/**
290→ * Restore an item from the recycle bin back to a folder.
291→ *
292→ * Removes the entry from bin metadata, adds the preserved FolderChild
293→ * back to the target folder's children, and publishes both.
294→ */
295→export async function restoreFromBin(params: {
296→  entryId: string;
297→  targetFolderIpnsName: string;
298→  folderTree: FolderTree;
299→  binState: BinState;
300→  binCtx: BinOperationContext;
301→}): Promise<{ restoredItem: FolderChild; updatedBinState: BinState }> {
302→  // 1. Find the bin entry
303→  const entry = params.binState.entries.find((e) => e.id === params.entryId);
304→  if (!entry) throw new Error('Bin entry not found');
305→
306→  // 2. Get the FolderChild to restore
307→  let child: FolderChild;
308→  if (entry.itemType === 'file' && entry.filePointer) {
309→    child = { ...entry.filePointer, modifiedAt: Date.now() };
310→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
311→    child = { ...entry.folderEntry, modifiedAt: Date.now() };
312→  } else {
313→    throw new Error('Bin entry has no stored item reference');
314→  }
315→
316→  // 3. Add child back to target folder
317→  const targetFolder = params.folderTree.get(params.targetFolderIpnsName);
318→  if (!targetFolder) throw new Error('Target folder not loaded');
319→
320→  // Handle name collisions
321→  const existingNames = new Set(targetFolder.children.map((c) => c.name));
322→  if (existingNames.has(child.name)) {
323→    let newName = `${child.name} (restored)`;
324→    let counter = 2;
325→    while (existingNames.has(newName)) {
326→      newName = `${child.name} (restored ${counter})`;
327→      counter++;
328→    }
329→    child = { ...child, name: newName };
330→  }
331→
332→  const updatedFolderChildren = [...targetFolder.children, child];
333→
334→  // 4. Publish updated folder metadata
335→  const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
336→    children: updatedFolderChildren,
337→    folderKey: targetFolder.folderKey,
338→    ipnsPrivateKey: targetFolder.ipnsKeypair.privateKey,
339→    ipnsName: params.targetFolderIpnsName,
340→    sequenceNumber: targetFolder.sequenceNumber,
341→    ctx: params.binCtx.ctx,
342→  });
343→
344→  // 5. Update folder state
345→  targetFolder.children = updatedFolderChildren;
346→  targetFolder.sequenceNumber = newSequenceNumber;
347→  targetFolder.lastLoadedAt = Date.now();
348→  params.folderTree.set(params.targetFolderIpnsName, targetFolder);
349→
350→  // 6. Remove entry from bin and publish
351→  const remainingEntries = params.binState.entries.filter((e) => e.id !== params.entryId);
352→  const newBinSeq = params.binState.sequenceNumber + 1;
353→
354→  const metadata: RecycleBinMetadata = {
355→    version: BIN_METADATA_VERSION,
356→    sequenceNumber: newBinSeq,
357→    entries: remainingEntries,
358→  };
359→
360→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
361→
362→  const updatedBinState: BinState = {
363→    entries: remainingEntries,
364→    sequenceNumber: newBinSeq,
365→    ipnsName: params.binState.ipnsName,
366→  };
367→
368→  return { restoredItem: child, updatedBinState };
369→}
