371→/**
372→ * Permanently delete a bin entry (unpin CIDs, remove from bin metadata).
373→ *
374→ * For files: unpins the content CID if available.
375→ * Does NOT handle recursive folder cleanup (that requires deep IPNS traversal).
376→ */
377→export async function permanentDeleteFromBin(params: {
378→  entryId: string;
379→  binState: BinState;
380→  binCtx: BinOperationContext;
381→}): Promise<{ updatedBinState: BinState }> {
382→  const entry = params.binState.entries.find((e) => e.id === params.entryId);
383→  if (!entry) throw new Error('Bin entry not found');
384→
385→  // Unpin content CID if available (best-effort)
386→  if (entry.contentCid) {
387→    try {
388→      await sdkCore.unpinFromIpfs(params.binCtx.ctx, entry.contentCid);
389→    } catch {
390→      // Best-effort CID cleanup
391→    }
392→  }
393→
394→  // Remove from bin metadata and publish
395→  const remainingEntries = params.binState.entries.filter((e) => e.id !== params.entryId);
396→  const newBinSeq = params.binState.sequenceNumber + 1;
397→
398→  const metadata: RecycleBinMetadata = {
399→    version: BIN_METADATA_VERSION,
400→    sequenceNumber: newBinSeq,
401→    entries: remainingEntries,
402→  };
403→
404→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
405→
406→  return {
407→    updatedBinState: {
408→      entries: remainingEntries,
409→      sequenceNumber: newBinSeq,
410→      ipnsName: params.binState.ipnsName,
411→    },
412→  };
413→}
414→
415→/**
416→ * Empty the bin by permanently deleting all entries.
417→ *
418→ * Cleans up CIDs (best-effort) and publishes empty bin metadata.
419→ */
420→export async function emptyBin(params: {
421→  binState: BinState;
422→  binCtx: BinOperationContext;
423→}): Promise<{ updatedBinState: BinState }> {
424→  // Best-effort CID cleanup for each entry
425→  for (const entry of params.binState.entries) {
426→    if (entry.contentCid) {
427→      try {
428→        await sdkCore.unpinFromIpfs(params.binCtx.ctx, entry.contentCid);
429→      } catch {
430→        // Non-blocking
431→      }
432→    }
433→  }
434→
435→  // Publish empty bin metadata
436→  const newBinSeq = params.binState.sequenceNumber + 1;
437→  const metadata: RecycleBinMetadata = {
438→    version: BIN_METADATA_VERSION,
439→    sequenceNumber: newBinSeq,
440→    entries: [],
441→  };
442→
443→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
444→
445→  return {
446→    updatedBinState: {
447→      entries: [],
448→      sequenceNumber: newBinSeq,
449→      ipnsName: params.binState.ipnsName,
450→    },
451→  };
452→}
