105→ * Folder metadata read workload (IPNS resolve + IPFS fetch + decrypt).
106→ *
107→ * Uses loadFolderMetadata which resolves IPNS, fetches the CID,
108→ * and decrypts the folder metadata -- the full read path.
109→ */
110→export async function runFolderReadWorkload(
111→  swc: SdkWorkloadClient,
112→  opts: { cycles: number }
113→): Promise<void> {
114→  const { pc, ctx } = swc;
